259	fn setQosClass(self: *const Thread) void {
260	    // Thread QoS classes are only relevant on macOS.
261	    if (comptime !builtin.target.os.tag.isDarwin()) return;
262	
263	    const class: internal_os.macos.QosClass = class: {
264	        // If we aren't visible (our view is fully occluded) then we
265	        // always drop our rendering priority down because it's just
266	        // mostly wasted work.
267	        //
268	        // The renderer itself should be doing this as well (for example
269	        // Metal will stop our DisplayLink) but this also helps with
270	        // general forced updates and CPU usage i.e. a rebuild cells call.
271	        if (!self.flags.visible) break :class .utility;
272	
273	        // If we're not focused, but we're visible, then we set a higher
274	        // than default priority because framerates still matter but it isn't
275	        // as important as when we're focused.
276	        if (!self.flags.focused) break :class .user_initiated;
277	
278	        // We are focused and visible, we are the definition of user interactive.
279	        break :class .user_interactive;
280	    };
281	
282	    if (internal_os.macos.setQosClass(class)) {
283	        log.debug("thread QoS class set class={}", .{class});
284	    } else |err| {
285	        log.warn("error setting QoS class err={}", .{err});
286	    }
287	}
